import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import DiscussionControls from 'flarum/forum/utils/DiscussionControls';
import DiscussionClickStatsModal from './components/DiscussionClickStatsModal';
export default function extendDiscussionControls() {
  extend(DiscussionControls, 'moderationControls', function (items, discussion) {
    if (!app.forum.attribute('canViewLinkClickAnalytics')) return;
    items.add('datlechin-link-clicks.stats', m(Button, {
      icon: "fas fa-chart-line",
      onclick: () => app.modal.show(DiscussionClickStatsModal, {
        discussionId: Number(discussion.id()),
        discussionTitle: discussion.title()
      })
    }, app.translator.trans('datlechin-link-clicks.forum.discussion_controls.click_stats')), -5);
  });
}