import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Button from 'flarum/common/components/Button';
import PostControls from 'flarum/forum/utils/PostControls';
const saving = new Set();
export default function extendPostControls() {
  extend(PostControls, 'moderationControls', function (items, post) {
    if (post.contentType() !== 'comment' || !post.canEdit()) return;
    const disabled = !!post.attribute('linkClicksDisabled');
    const postId = Number(post.id());
    items.add('linkClicksToggle', m(Button, {
      icon: disabled ? 'fas fa-link' : 'fas fa-link-slash',
      loading: saving.has(postId),
      onclick: () => {
        saving.add(postId);
        m.redraw();
        post.save({
          linkClicksDisabled: !disabled
        }).then(() => {
          saving.delete(postId);
          m.redraw();
        }, err => {
          saving.delete(postId);
          app.alerts.show({
            type: 'error'
          }, app.translator.trans('datlechin-link-clicks.forum.post_controls.toggle_failed'));
          m.redraw();
          throw err;
        });
      }
    }, app.translator.trans(disabled ? 'datlechin-link-clicks.forum.post_controls.enable_tracking' : 'datlechin-link-clicks.forum.post_controls.disable_tracking')), -10);
  });
}